/**
 * Songs for the emotes, heard by everyone nearby.
 *
 * WHERE THE MUSIC COMES FROM (honestly): every sample here is generated by the code below, from
 * sine, sawtooth, pulse and noise maths, with melodies and chord loops written for this game.
 * There are no recordings and no files. Nothing is a transcription of any existing song: the emotes
 * are NAMED after dances (Macarena, YMCA, Thriller) but the music is generic genre writing, in
 * the sense that a "latin dance-pop" or "disco" loop is a drum pattern + bass + chords, none of
 * which is anyone's property:
 *   latin   dembow drum pattern (kick on the quarters, snare on 3-3-2) + a pentatonic hook over
 *           the Andalusian cadence (Am G F E, one of the most common progressions in pop)
 *   funk    swung 16ths, a syncopated bass over minor-seventh stabs
 *   chip    "oom-pah" square waves, a bouncy arpeggio tune in G major
 *   disco   four on the floor, octave bass, strings, over i-VI-III-VII
 *   spooky  half-time minor drums, a phrygian bass ostinato (not the Thriller line), plucked arp
 *   electro four on the floor, a bit-crushed staccato lead, saw bass
 *   fanfare brass stabs, a march snare, rising arpeggios in C major
 * The emote wheel's "wave" has no song (it keeps the generic loop in audio.js).
 *
 * HOW IT PLAYS: each song is rendered once, on first use, into a mono AudioBuffer (22.05 kHz,
 * 14-20 s, in slices a bar at a time so no frame stalls). A voice is then one looping
 * AudioBufferSourceNode through a gain and an equal-power panner into Audio.music, so the music
 * slider and the master volume apply, and it is placed in the world (louder when near, panned
 * left/right). Nothing is scheduled note by note, so a voice costs one node chain; at most
 * MAX_VOICES play at once (the nearest), and the 120 ms timer only exists while somebody dances.
 *
 * Callers do not start and stop voices by hand: they call play(key, emoteId, x, y, z) every frame
 * the emote is on, and stop(key) when it ends. A voice not refreshed for STALE_MS (a puppet that
 * left, a dropped connection, a stalled tab) is stopped by itself.
 */

export const SR = 22050;
const TAU = Math.PI * 2;

/** Which song each emote plays. Emotes not listed are silent (and keep the generic loop). */
export const SONG_FOR_EMOTE = {
  macarena: 'latin', hiphop: 'funk', chicken: 'chip', ymca: 'disco', thriller: 'spooky', robot: 'electro', victory: 'fanfare',
};

const mtof = (n) => 440 * 2 ** ((n - 69) / 12);

/** A small seeded generator, so a song renders identically every time. */
function rng(seed) {
  let a = seed | 0;
  return () => {
    a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* ------------------------------------------------------------------ the synth */

class Mix {
  constructor(sr, seconds, seed) {
    this.sr = sr;
    this.n = Math.round(seconds * sr);
    this.buf = new Float32Array(this.n);
    this.rand = rng(seed);
  }

  /** Where in the buffer a time is. Notes that run past the end wrap round to the start. */
  at(t) { return Math.round(t * this.sr); }

  put(i, v) {
    if (i >= this.n) i -= this.n;
    this.buf[i] += v;
  }

  kick(t, g = 1) {
    const i0 = this.at(t), len = Math.floor(0.24 * this.sr);
    let ph = 0;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      ph += (TAU * (46 + 100 * Math.exp(-tt * 30))) / this.sr;
      this.put(i0 + k, Math.sin(ph) * Math.exp(-tt * 13) * g);
    }
  }

  snare(t, g = 1) {
    const i0 = this.at(t), len = Math.floor(0.2 * this.sr);
    let prev = 0;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      const n = this.rand() * 2 - 1;
      const hp = n - prev * 0.55; prev = n;
      this.put(i0 + k, (hp * Math.exp(-tt * 20) * 0.55 + Math.sin(TAU * 185 * tt) * Math.exp(-tt * 32) * 0.45) * g);
    }
  }

  clap(t, g = 1) {
    const i0 = this.at(t), len = Math.floor(0.2 * this.sr);
    let prev = 0;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      const n = this.rand() * 2 - 1;
      const hp = n - prev * 0.4; prev = n;
      const burst = Math.exp(-(tt % 0.011) * 160) * (tt < 0.033 ? 1 : 0);
      this.put(i0 + k, hp * (burst * 0.6 + Math.exp(-tt * 20) * 0.5) * g);
    }
  }

  hat(t, g = 1, open = false) {
    const i0 = this.at(t), len = Math.floor((open ? 0.22 : 0.05) * this.sr), d = open ? 16 : 85;
    let prev = 0;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      const n = this.rand() * 2 - 1;
      this.put(i0 + k, (n - prev) * Math.exp(-tt * d) * 0.5 * g); prev = n;
    }
  }

  shaker(t, g = 1) {
    const i0 = this.at(t), len = Math.floor(0.07 * this.sr);
    let prev = 0;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      const n = this.rand() * 2 - 1;
      this.put(i0 + k, (n - prev) * Math.min(1, tt * 400) * Math.exp(-tt * 45) * 0.4 * g); prev = n;
    }
  }

  conga(t, g = 1, hi = false) {
    const i0 = this.at(t), len = Math.floor(0.18 * this.sr), f = hi ? 330 : 245;
    let ph = 0;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      ph += (TAU * f * (1 + 0.18 * Math.exp(-tt * 45))) / this.sr;
      this.put(i0 + k, (Math.sin(ph) * Math.exp(-tt * 24) + (this.rand() * 2 - 1) * Math.exp(-tt * 350) * 0.3) * g);
    }
  }

  clave(t, g = 1) {
    const i0 = this.at(t), len = Math.floor(0.07 * this.sr);
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      this.put(i0 + k, (Math.sin(TAU * 2400 * tt) + 0.5 * Math.sin(TAU * 3600 * tt)) * Math.exp(-tt * 70) * 0.5 * g);
    }
  }

  /** A saw or square through a low-pass that closes as the note rings. */
  bass(t, f, dur, g = 1, wave = 'saw', cut = 0.16) {
    const i0 = this.at(t), len = Math.floor((dur + 0.04) * this.sr);
    let ph = 0, y = 0;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      ph += f / this.sr;
      const fr = ph - Math.floor(ph);
      const x = wave === 'square' ? (fr < 0.5 ? 1 : -1) : 2 * fr - 1;
      y += cut * (0.35 + 0.65 * Math.exp(-tt * 9)) * (x - y);
      const amp = Math.min(1, tt / 0.004) * Math.min(1, Math.max(0, (dur + 0.03 - tt) / 0.03));
      this.put(i0 + k, y * amp * g);
    }
  }

  /** A plucked keyboard: three partials that die away at different rates. */
  keys(t, f, dur, g = 1) {
    const i0 = this.at(t), len = Math.floor((dur + 0.25) * this.sr);
    const w = TAU * f / this.sr;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      const v = Math.sin(w * k) + 0.45 * Math.sin(2 * w * k) * Math.exp(-tt * 7) + 0.2 * Math.sin(3 * w * k) * Math.exp(-tt * 11);
      this.put(i0 + k, v * Math.exp(-tt * 5.5) * Math.min(1, tt / 0.003) * 0.5 * g);
    }
  }

  /** A pulse-wave lead. `crush` holds each value for that many samples, for a robotic grain. */
  lead(t, f, dur, g = 1, { duty = 0.5, vib = 0, crush = 1 } = {}) {
    const i0 = this.at(t), len = Math.floor((dur + 0.04) * this.sr);
    let ph = 0, held = 0;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      ph += (f * (1 + vib * Math.sin(TAU * 5.5 * tt))) / this.sr;
      if (k % crush === 0) held = ph - Math.floor(ph) < duty ? 1 : -1;
      const amp = Math.min(1, tt / 0.004) * Math.min(1, Math.max(0, (dur + 0.03 - tt) / 0.03)) * (0.8 + 0.2 * Math.exp(-tt * 8));
      this.put(i0 + k, held * amp * 0.5 * g);
    }
  }

  /** A chord of saws, low-passed: a string or brass stab. `decay` is how fast it dies away. */
  stab(t, notes, dur, g = 1, decay = 6, cut = 0.2) {
    const i0 = this.at(t), len = Math.floor((dur + 0.05) * this.sr);
    const ph = notes.map(() => 0), inc = notes.map((n) => mtof(n) / this.sr);
    let y = 0;
    for (let k = 0; k < len; k++) {
      const tt = k / this.sr;
      let x = 0;
      for (let j = 0; j < ph.length; j++) { ph[j] += inc[j]; x += 2 * (ph[j] - Math.floor(ph[j])) - 1; }
      y += cut * (x / ph.length - y);
      const amp = Math.min(1, tt / 0.008) * Math.exp(-tt * decay) * Math.min(1, Math.max(0, (dur + 0.04 - tt) / 0.04));
      this.put(i0 + k, y * amp * g);
    }
  }

  /** A slow detuned pad. */
  pad(t, notes, dur, g = 1) {
    const i0 = this.at(t), len = Math.floor(dur * this.sr);
    const ph = [], inc = [];
    for (const n of notes) for (const d of [0.996, 1.004]) { ph.push(0); inc.push((mtof(n) * d) / this.sr); }
    let y = 0;
    for (let k = 0; k < len; k++) {
      let x = 0;
      for (let j = 0; j < ph.length; j++) { ph[j] += inc[j]; x += 2 * (ph[j] - Math.floor(ph[j])) - 1; }
      y += 0.07 * (x / ph.length - y);
      const u = k / len;
      this.put(i0 + k, y * Math.sin(Math.PI * Math.min(1, u * 1.15)) * g);
    }
  }
}

/** Triad tones by index: 0 root, 1 third, 2 fifth, 3 octave... */
const tone = (tri, i) => tri[i % 3] + 12 * Math.floor(i / 3);

/* ------------------------------------------------------------------- the songs */

const SONGS = {
  // Latin dance-pop: dembow drums, tumbao-ish bass, offbeat piano stabs, and a pentatonic hook
  // over Am G F E that comes in for the second half.
  latin: {
    bpm: 100, bars: 8, swing: 0,
    play(m, bar, s, t, sx) {
      const c = bar % 4, root = [45, 43, 41, 40][c];
      const tri = [[57, 60, 64], [55, 59, 62], [53, 57, 60], [52, 56, 59]][c];
      if (s % 4 === 0) m.kick(t, 0.9);
      if (s === 3 || s === 6 || s === 11 || s === 14) m.snare(t, 0.5);
      if (s === 2 || s === 7 || s === 10 || s === 15) m.conga(t, 0.5, s === 7 || s === 15);
      if (s % 2 === 0) m.shaker(t, s % 4 === 0 ? 0.6 : 0.4);
      if (s === 0 || s === 8 || s === 14) m.bass(t, mtof(root), sx * 3, 0.5, 'saw', 0.12);
      if (s === 6) m.bass(t, mtof(root + 7), sx * 2, 0.4, 'saw', 0.12);
      if (s === 2 || s === 6 || s === 10 || s === 14) for (const n of tri) m.keys(t, mtof(n + 12), sx * 1.4, 0.16);
      if (bar >= 4) {
        const hook = [
          [[0, 81, 2], [3, 79, 1], [4, 76, 2], [8, 76, 1], [10, 79, 2], [13, 76, 1]],
          [[0, 79, 2], [3, 76, 1], [4, 74, 2], [8, 74, 1], [10, 76, 2], [13, 74, 1]],
          [[0, 77, 2], [3, 76, 1], [4, 72, 2], [8, 72, 1], [10, 76, 2], [13, 72, 1]],
          [[0, 80, 2], [3, 76, 1], [4, 71, 2], [8, 76, 2], [11, 80, 1], [12, 83, 3]],
        ][c];
        for (const [st, n, d] of hook) if (st === s) m.lead(t, mtof(n), sx * d * 0.9, 0.34, { duty: 0.35, vib: 0.004 });
      }
    },
  },

  // Funk: swung sixteenths, a syncopated bass, minor-seventh stabs.
  funk: {
    bpm: 92, bars: 8, swing: 0.3,
    play(m, bar, s, t, sx) {
      const root = [40, 40, 45, 45, 40, 40, 47, 40][bar];
      const chord = [[52, 55, 59, 62], [52, 55, 59, 62], [57, 60, 64, 67], [57, 60, 64, 67], [52, 55, 59, 62], [52, 55, 59, 62], [59, 63, 66, 69], [52, 55, 59, 62]][bar];
      if (s === 0 || s === 7 || s === 10 || (bar % 4 === 3 && s === 14)) m.kick(t, 0.95);
      if (s === 4 || s === 12) m.snare(t, 0.85);
      m.hat(t, s % 2 === 0 ? 0.55 : 0.3, s === 14 && bar % 2 === 1);
      for (const [st, off, d] of [[0, 0, 2], [3, 0, 1], [5, 12, 1], [7, 10, 1], [10, 0, 2], [13, 7, 1], [14, 5, 1]]) {
        if (st === s) m.bass(t, mtof(root + off), sx * d * 0.9, 0.55, 'saw', 0.14);
      }
      if (s === 2 || s === 5 || s === 10 || s === 13) for (const n of chord) m.keys(t, mtof(n + 12), sx * 1.5, 0.15);
      if (bar >= 4 && (s === 8 || s === 11) ) m.lead(t, mtof(chord[3] + 24), sx * 2, 0.22, { duty: 0.25, vib: 0.006 });
    },
  },

  // Chiptune: oom-pah square waves under a bouncing arpeggio tune in G major.
  chip: {
    bpm: 136, bars: 8, swing: 0,
    play(m, bar, s, t, sx) {
      const c = [0, 1, 2, 0, 0, 1, 2, 0][bar];
      const root = [43, 48, 50][c], tri = [[55, 59, 62], [60, 64, 67], [62, 66, 69]][c];
      if (s === 0 || s === 8) m.bass(t, mtof(root), sx * 3, 0.5, 'square', 0.3);
      if (s === 4 || s === 12) for (const n of tri) m.lead(t, mtof(n), sx * 2, 0.12, { duty: 0.25 });
      if (s === 4 || s === 12) m.snare(t, 0.35);
      if (s % 2 === 0) m.hat(t, 0.25);
      const tune = [
        [[0, 79, 2], [2, 83, 2], [4, 86, 2], [6, 83, 2], [8, 79, 2], [10, 83, 2], [12, 86, 4]],
        [[0, 84, 2], [2, 79, 2], [4, 76, 2], [6, 79, 2], [8, 84, 2], [10, 79, 2], [12, 76, 4]],
        [[0, 81, 2], [2, 86, 2], [4, 90, 2], [6, 86, 2], [8, 81, 2], [10, 86, 2], [12, 90, 4]],
      ][c];
      for (const [st, n, d] of tune) if (st === s) m.lead(t, mtof(n + (bar === 7 && st === 12 ? 12 : 0)), sx * d * 0.85, 0.3, { duty: 0.5, vib: 0.003 });
    },
  },

  // Disco: four on the floor, octave bass, string pads and stabs over Dm Bb F C.
  disco: {
    bpm: 124, bars: 8, swing: 0,
    play(m, bar, s, t, sx) {
      const c = bar % 4, root = [38, 34, 41, 36][c];
      const tri = [[62, 65, 69], [58, 62, 65], [65, 69, 72], [60, 64, 67]][c];
      if (s % 4 === 0) m.kick(t, 0.9);
      if (s === 4 || s === 12) m.clap(t, 0.65);
      if (s % 4 === 2) m.hat(t, 0.55, true);
      if (s % 2 === 1) m.hat(t, 0.18);
      if (s % 2 === 0) m.bass(t, mtof(root + (s % 4 === 2 ? 12 : 0)), sx * 1.7, 0.5, 'saw', 0.13);
      if (s === 0) m.pad(t, tri, sx * 16, 0.2);
      if (s === 6 || s === 10) m.stab(t, tri.map((n) => n + 12), sx * 2, 0.22, 7, 0.3);
      if (bar >= 4) {
        const hook = [[0, 3, 2], [3, 4, 1], [4, 5, 3], [8, 4, 2], [11, 3, 1], [12, 2, 4]];
        for (const [st, i, d] of hook) if (st === s) m.lead(t, mtof(tone(tri, i + 3)), sx * d * 0.9, 0.3, { duty: 0.4, vib: 0.005 });
      }
    },
  },

  // Spooky: half-time minor drums, a phrygian bass ostinato, a plucked arpeggio, a held organ.
  spooky: {
    bpm: 108, bars: 8, swing: 0.12,
    play(m, bar, s, t, sx) {
      const root = [33, 33, 34, 33, 33, 33, 29, 28][bar];
      const minor = bar === 7 ? [52, 56, 59] : bar === 6 ? [53, 57, 60] : bar === 2 ? [58, 62, 65] : [57, 60, 64];
      if (s === 0 || s === 6 || s === 10) m.kick(t, 0.9);
      if (s === 8) m.snare(t, 0.8);
      if (s % 2 === 0) m.hat(t, s % 4 === 2 ? 0.4 : 0.22);
      for (const [st, off, d] of [[0, 0, 2], [3, 0, 1], [6, 1, 1], [8, 0, 2], [11, 3, 1], [14, 1, 1]]) {
        if (st === s) m.bass(t, mtof(root + off), sx * d * 0.9, 0.6, 'saw', 0.1);
      }
      if (s % 2 === 0) {
        const arp = [0, 1, 2, 1, 0, 2][(s / 2 + bar) % 6];
        m.keys(t, mtof(minor[arp] + 12 + (s === 4 ? 12 : 0)), sx * 1.5, 0.12);
      }
      if (s === 0 && bar % 2 === 0) m.pad(t, minor, sx * 32, 0.17);
      if (s === 12 && bar % 4 === 3) m.keys(t, mtof(93), sx * 3, 0.1);
    },
  },

  // Electro: four on the floor, saw bass, a bit-crushed staccato lead and a robotic arpeggio.
  electro: {
    bpm: 120, bars: 8, swing: 0,
    play(m, bar, s, t, sx) {
      const c = [0, 0, 1, 2, 0, 0, 1, 2][bar];
      const root = [40, 36, 38][c], tri = [[64, 67, 71], [60, 64, 67], [62, 66, 69]][c];
      if (s % 4 === 0) m.kick(t, 0.9);
      if (s === 4 || s === 12) m.clap(t, 0.6);
      m.hat(t, s % 4 === 2 ? 0.45 : 0.15, s % 4 === 2);
      if (s % 2 === 0) m.bass(t, mtof(root + (s === 14 ? 12 : 0)), sx * 1.6, 0.5, 'saw', 0.12);
      m.lead(t, mtof(tone(tri, [0, 1, 2, 1][s % 4] + 3)), sx * 0.8, 0.17, { duty: 0.25, crush: 3 });
      if (bar >= 4) {
        for (const [st, n, d] of [[0, 76, 1], [2, 76, 1], [4, 79, 1], [6, 76, 1], [8, 83, 2], [12, 79, 2]]) {
          if (st === s) m.lead(t, mtof(n), sx * d * 0.8, 0.3, { duty: 0.5, crush: 5 });
        }
      }
    },
  },

  // Victory fanfare: brass stabs, a marching snare with a roll, rising arpeggios in C major.
  fanfare: {
    bpm: 126, bars: 8, swing: 0,
    play(m, bar, s, t, sx) {
      const c = [0, 1, 2, 0, 3, 1, 2, 0][bar];
      const root = [36, 41, 43, 45][c], tri = [[60, 64, 67], [65, 69, 72], [67, 71, 74], [69, 72, 76]][c];
      if (s === 0 || s === 8) m.kick(t, 0.9);
      if (s === 4 || s === 12) m.snare(t, 0.6);
      if ((bar === 3 || bar === 7) && s >= 12) m.snare(t, 0.2 + (s - 12) * 0.12);
      if (s % 4 === 0) m.bass(t, mtof(root), sx * 3, 0.5, 'square', 0.2);
      if (s === 0 || s === 6 || s === 10) m.stab(t, tri, sx * (s === 0 ? 5 : 3), 0.32, 1.6, 0.3);
      if (s % 2 === 0 && s >= 2) m.lead(t, mtof(tone(tri, ((s / 2) + bar) % 5 + 3)), sx * 1.6, 0.18, { duty: 0.5, vib: 0.004 });
    },
  },
};

/** How long a song lasts, in seconds. */
export const songLength = (id) => (60 / SONGS[id].bpm) * 4 * SONGS[id].bars;
export const SONG_IDS = Object.keys(SONGS);

/**
 * Render a song to a mono Float32Array. Deterministic. Calls `pause()` (if given and it returns a
 * promise) between bars, so a caller can hand the main thread back and keep frames flowing.
 */
export async function renderSong(id, sr = SR, pause = null) {
  const song = SONGS[id];
  if (!song) return null;
  const sx = 60 / song.bpm / 4;
  const m = new Mix(sr, sx * 16 * song.bars, 1000 + SONG_IDS.indexOf(id));
  for (let bar = 0; bar < song.bars; bar++) {
    for (let s = 0; s < 16; s++) {
      song.play(m, bar, s, (bar * 16 + s) * sx + (s % 2 === 1 ? song.swing * sx : 0), sx);
    }
    if (pause) await pause();
  }
  // Level to a fixed loudness (so no song is louder than another), then soft-clip the peaks.
  let sum = 0;
  for (let i = 0; i < m.n; i++) sum += m.buf[i] * m.buf[i];
  const k = 0.14 / Math.max(1e-6, Math.sqrt(sum / m.n));
  for (let i = 0; i < m.n; i++) m.buf[i] = Math.tanh(m.buf[i] * k);
  return m.buf;
}

/* ------------------------------------------------------------------ the voices */

const MAX_VOICES = 3;        // simultaneous songs: the nearest
const MAX_DIST = 42;         // m: past this a song is not played at all
const FADE_BAND = 10;        // m: it fades out over the last stretch before MAX_DIST
const STALE_MS = 700;        // a voice not refreshed for this long is stopped
const TICK_MS = 120;         // how often voices are chosen; 0 timers while nobody dances
const VOICE_GAIN = 0.55;

/**
 * `Audio` is src/audio.js's runtime (ctx, music bus, ready), `getCamera` returns the listener's
 * camera. Panning is equal-power whatever the power setting: it is already the cheap model.
 */
export function createEmoteMusic({ Audio, getCamera, pause = () => new Promise((r) => setTimeout(r, 0)) }) {
  const wanted = new Map();     // key -> { song, x, y, z, seen, since, voice }
  const buffers = new Map();    // song id -> AudioBuffer, or 'loading'
  let timer = null;
  const nearest = new Array(MAX_VOICES).fill(null);
  const nearestD = new Array(MAX_VOICES).fill(0);

  function bufferFor(song) {
    const have = buffers.get(song);
    if (have && have !== 'loading') return have;
    if (!have && Audio.ctx) {
      buffers.set(song, 'loading');
      renderSong(song, SR, pause).then((data) => {
        if (!data || !Audio.ctx) { buffers.delete(song); return; }
        const b = Audio.ctx.createBuffer(1, data.length, SR);
        b.copyToChannel(data, 0);
        buffers.set(song, b);
      }, () => buffers.delete(song));
    }
    return null;
  }

  function startVoice(e, vol) {
    const ctx = Audio.ctx, buf = bufferFor(e.song);
    if (!buf) return;
    const now = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = buf; src.loop = true;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, now);
    gain.gain.linearRampToValueAtTime(VOICE_GAIN * vol, now + 0.15);
    const pan = ctx.createPanner();
    pan.panningModel = 'equalpower';       // HRTF is a convolution per voice; this is for a dance loop
    pan.distanceModel = 'inverse';
    pan.refDistance = 6; pan.rolloffFactor = 1.1;
    place(pan, e);
    src.connect(gain); gain.connect(pan); pan.connect(Audio.music);
    // Join the song where the dance is up to, so walking out of range and back does not restart it.
    const len = buf.duration;
    src.start(0, (((performance.now() - e.since) / 1000) % len + len) % len);
    e.voice = { src, gain, pan };
  }

  function place(pan, e) {
    if (pan.positionX) { pan.positionX.value = e.x; pan.positionY.value = e.y; pan.positionZ.value = e.z; }
    else pan.setPosition(e.x, e.y, e.z);
  }

  function stopVoice(e) {
    const v = e.voice;
    if (!v) return;
    e.voice = null;
    const now = Audio.ctx.currentTime;
    v.gain.gain.cancelScheduledValues(now);
    v.gain.gain.setTargetAtTime(0, now, 0.04);
    v.src.onended = () => { v.src.disconnect(); v.gain.disconnect(); v.pan.disconnect(); };
    try { v.src.stop(now + 0.25); } catch { /* already stopped */ }
  }

  function choose() {
    const live = Audio.ready && Audio.ctx && Audio.ctx.state === 'running' && !(typeof document !== 'undefined' && document.hidden);
    const now = performance.now();
    const cam = getCamera().position;
    nearest.fill(null);
    for (const [key, e] of wanted) {
      if (now - e.seen > STALE_MS || !live) {
        if (e.voice) stopVoice(e);
        if (now - e.seen > STALE_MS) wanted.delete(key);
        continue;
      }
      const d = key === 'self' ? 0 : Math.hypot(e.x - cam.x, e.y - cam.y, e.z - cam.z);
      e.d = d;
      if (d >= MAX_DIST) continue;
      // Insert into the (at most MAX_VOICES long) nearest list.
      for (let i = 0; i < MAX_VOICES; i++) {
        if (nearest[i] === null || d < nearestD[i]) {
          for (let j = MAX_VOICES - 1; j > i; j--) { nearest[j] = nearest[j - 1]; nearestD[j] = nearestD[j - 1]; }
          nearest[i] = e; nearestD[i] = d;
          break;
        }
      }
    }
    if (live) {
      for (const e of wanted.values()) {
        if (!nearest.includes(e) && e.voice) stopVoice(e);
      }
      const t = Audio.ctx.currentTime;
      for (const e of nearest) {
        if (!e) continue;
        const fade = Math.min(1, (MAX_DIST - e.d) / FADE_BAND);
        if (!e.voice) startVoice(e, fade);
        else e.voice.gain.gain.setTargetAtTime(VOICE_GAIN * fade, t, 0.08);
      }
    }
    if (!wanted.size) { clearInterval(timer); timer = null; }
  }

  return {
    /** Keep `key`'s song going (call every frame it is dancing); `emote` is the emote id. */
    play(key, emote, x, y, z) {
      const song = SONG_FOR_EMOTE[emote];
      if (!song) { this.stop(key); return; }
      let e = wanted.get(key);
      if (e && e.song !== song) { if (e.voice) stopVoice(e); wanted.delete(key); e = undefined; }
      if (!e) {
        e = { song, x, y, z, seen: 0, since: performance.now(), voice: null, d: 0 };
        wanted.set(key, e);
      }
      e.x = x; e.y = y; e.z = z; e.seen = performance.now();
      if (e.voice) place(e.voice.pan, e);
      if (!timer) timer = setInterval(choose, TICK_MS);
    },
    stop(key) {
      const e = wanted.get(key);
      if (!e) return;
      if (e.voice) stopVoice(e);
      wanted.delete(key);
    },
    stopAll() { for (const key of [...wanted.keys()]) this.stop(key); },
    songFor: (emote) => SONG_FOR_EMOTE[emote] ?? null,
    /** For tests and the debug overlay: how many songs are sounding right now. */
    get voices() { let n = 0; for (const e of wanted.values()) if (e.voice) n++; return n; },
    get dancers() { return wanted.size; },
    get timerRunning() { return timer !== null; },
    /** Run the voice chooser now instead of waiting for the timer (tests). */
    _tick: choose,
  };
}
